def is_safe_tar_member(member, dest_path):
    # Check if the member path is within the destination directory
    member_path = os.path.join(dest_path, member.name)
    return os.path.commonprefix([os.path.abspath(dest_path), os.path.abspath(member_path)]) == os.path.abspath(dest_path)

